1	export type Item = {
2	  type: string;
3	  material?: string;
4	  enchantment?: number;
5	  cursed?: boolean;
6	};
7	
8	export type QuoteStep = {
9	  op: "quote";
10	  items: Item[];
11	};
12	
13	export type Damage = {
14	  itemType: string;
15	  amount: number;
16	};
17	
18	export type ClaimStep = {
19	  op: "claim";
20	  policy: number;
21	  incident: { cause: string; damages: Damage[] };
22	};
23	
24	export type Step = QuoteStep | ClaimStep;
25	
26	export type Customer = {
27	  yearsWithMHPCO: number;
28	};
29	
30	export type Scenario = {
31	  customer: Customer;
32	  steps: Step[];
33	};
34	
35	export type ScenarioResults = {
36	  results: unknown[];
37	};
38	
39	const PROCESSING_FEE = 5;
40	const FIRST_INSURANCE_SURCHARGE = 0.1;
41	const CURSE_SURCHARGE = 0.5;
42	const HIGH_ENCHANTMENT_THRESHOLD = 5;
43	const HIGH_ENCHANTMENT_SURCHARGE = 0.3;
44	const LOYALTY_YEARS_THRESHOLD = 2;
45	const LOYALTY_DISCOUNT = 0.2;
46	const FOLLOW_UP_CONTRACT_DISCOUNT = 0.15;
47	const DEDUCTIBLE = 100;
48	const CAP_MULTIPLIER = 2;
49	const HIGH_ENCHANTMENT_CLAIM_THRESHOLD = 8;
50	const HIGH_ENCHANTMENT_REIMBURSEMENT = 0.5;
51	const DEFAULT_REIMBURSEMENT_RATE = 1;
52	
53	const INSURANCE_VALUES: Record<string, number> = {
54	  sword: 1000,
55	  amulet: 600,
56	  staff: 800,
57	  potion: 400,
58	  rune: 250,
59	  moonstone: 250,
60	};
61	
62	const ITEM_BASE_PREMIUMS: Record<string, number> = {
63	  sword: 100,
64	  amulet: 60,
65	  staff: 80,
66	  potion: 40,
67	  rune: 25,
68	  moonstone: 25,
69	};
70	
71	/** Premiums round up: the MHPCO's favour is the higher number. */
72	const roundPremiumInMHPCOsFavour = (premium: number): number =>
73	  Math.ceil(premium);
74	
75	/** Payouts round down: the MHPCO's favour is the lower number. */
76	const roundPayoutInMHPCOsFavour = (payout: number): number =>
77	  Math.floor(payout);
78	
79	const BLOCK_SIZE = 3;
80	const BLOCK_BASE_PREMIUM = 60;
81	
82	/** Tallies how many entries fall under each type, given how to read the type. */
83	const countByType = <T>(entries: T[], typeOf: (entry: T) => string) => {
84	  const counts = new Map<string, number>();
85	  for (const entry of entries) {
86	    const type = typeOf(entry);
87	    counts.set(type, (counts.get(type) ?? 0) + 1);
88	  }
89	  return counts;
90	};
91	
92	const itemType = (item: Item): string => item.type;
93	const damagedItemType = (damage: Damage): string => damage.itemType;
94	
95	const basePremiumForGroup = (type: string, count: number): number =>
96	  count === BLOCK_SIZE
97	    ? BLOCK_BASE_PREMIUM
98	    : count * ITEM_BASE_PREMIUMS[type];
99	
100	const policyBasePremium = (items: Item[]): number =>
101	  [...countByType(items, itemType)].reduce(
102	    (total, [type, count]) => total + basePremiumForGroup(type, count),
103	    0,
104	  );
105	
106	type SurchargeRule = {
107	  appliesTo: (item: Item) => boolean;
108	  rate: number;
109	};
110	
111	const SURCHARGE_RULES: SurchargeRule[] = [
112	  {
113	    appliesTo: (item) => item.cursed === true,
114	    rate: CURSE_SURCHARGE,
115	  },
116	  {
117	    appliesTo: (item) => (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD,
118	    rate: HIGH_ENCHANTMENT_SURCHARGE,
119	  },
120	];
121	
122	const itemSurcharge = (item: Item): number => {
123	  const itemBasePremium = ITEM_BASE_PREMIUMS[item.type];
124	  return SURCHARGE_RULES.filter((rule) => rule.appliesTo(item)).reduce(
125	    (surcharge, rule) => surcharge + itemBasePremium * rule.rate,
126	    0,
127	  );
128	};
129	
130	const sumItemSurcharges = (items: Item[]): number =>
131	  items.reduce((sum, item) => sum + itemSurcharge(item), 0);
132	
133	type PolicyContext = {
134	  customer: Customer;
135	  isFollowUpContract: boolean;
136	};
137	
138	type PolicyModifierRule = {
139	  appliesTo: (context: PolicyContext) => boolean;
140	  /** Signed rate applied to the policy base premium: positive adds, negative discounts. */
141	  rate: number;
142	};
143	
144	const POLICY_MODIFIER_RULES: PolicyModifierRule[] = [
145	  {
146	    appliesTo: () => true,
147	    rate: FIRST_INSURANCE_SURCHARGE,
148	  },
149	  {
150	    appliesTo: ({ customer }) =>
151	      customer.yearsWithMHPCO >= LOYALTY_YEARS_THRESHOLD,
152	    rate: -LOYALTY_DISCOUNT,
153	  },
154	  {
155	    appliesTo: ({ isFollowUpContract }) => isFollowUpContract,
156	    rate: -FOLLOW_UP_CONTRACT_DISCOUNT,
157	  },
158	];
159	
160	const sumPolicyModifiers = (
161	  basePremium: number,
162	  context: PolicyContext,
163	): number =>
164	  POLICY_MODIFIER_RULES.filter((rule) => rule.appliesTo(context)).reduce(
165	    (total, rule) => total + basePremium * rule.rate,
166	    0,
167	  );
168	
169	const quotePremium = (items: Item[], context: PolicyContext): number => {
170	  const basePremium = policyBasePremium(items);
171	  return roundPremiumInMHPCOsFavour(
172	    basePremium +
173	      sumItemSurcharges(items) +
174	      sumPolicyModifiers(basePremium, context) +
175	      PROCESSING_FEE,
176	  );
177	};
178	
179	const insuranceSum = (items: Item[]): number =>
180	  items.reduce((sum, item) => sum + INSURANCE_VALUES[item.type], 0);
181	
182	/**
183	 * The fraction of a damage amount the policy covers, before the deductible.
184	 *
185	 * The spec also states that dragon-material items are "fully reimbursed". That
186	 * clause is not listed here because full reimbursement is already the default
187	 * rate: in every spec example the two coincide, so no test can tell an explicit
188	 * dragon clause apart from this default. Adding one would be untested code.
189	 * A dragon clause only becomes observable if a future rule reduces the default
190	 * below 1 for some item a dragon-material item could also match.
191	 */
192	const reimbursementRateFor = (item: Item | undefined): number =>
193	  (item?.enchantment ?? 0) >= HIGH_ENCHANTMENT_CLAIM_THRESHOLD
194	    ? HIGH_ENCHANTMENT_REIMBURSEMENT
195	    : DEFAULT_REIMBURSEMENT_RATE;
196	
197	/** What the policy covers for one damaged item, before the deductible. */
198	const coveredAmountFor = (damage: Damage, insuredItems: Item[]): number => {
199	  const item = insuredItems.find(
200	    (candidate) => candidate.type === damage.itemType,
201	  );
202	  return damage.amount * reimbursementRateFor(item);
203	};
204	
205	/**
206	 * What the claim asks for, before the policy's remaining cap is applied.
207	 * The deductible is withheld once per damaged item.
208	 */
209	const desiredPayout = (damages: Damage[], insuredItems: Item[]): number =>
210	  damages.reduce(
211	    (sum, damage) => sum + coveredAmountFor(damage, insuredItems) - DEDUCTIBLE,
212	    0,
213	  );
214	
215	/**
216	 * Tracks how much cover each policy has left. A policy is identified by the
217	 * step index of the quote that created it, which is how claims refer to it.
218	 */
219	type PolicyLedger = {
220	  open: (policyId: number, items: Item[]) => void;
221	  insuredItems: (policyId: number) => Item[];
222	  /** Pays out at most the policy's remaining cap. */
223	  drawDown: (policyId: number, desiredPayout: number) => ClaimResult;
224	};
225	
226	const createPolicyLedger = (): PolicyLedger => {
227	  const remainingCaps = new Map<number, number>();
228	  const itemsByPolicy = new Map<number, Item[]>();
229	
230	  return {
231	    open: (policyId, items) => {
232	      remainingCaps.set(policyId, insuranceSum(items) * CAP_MULTIPLIER);
233	      itemsByPolicy.set(policyId, items);
234	    },
235	
236	    insuredItems: (policyId) => itemsByPolicy.get(policyId) ?? [],
237	
238	    drawDown: (policyId, desiredPayout) => {
239	      const cap = remainingCaps.get(policyId) ?? 0;
240	      const payout = Math.min(roundPayoutInMHPCOsFavour(desiredPayout), cap);
241	      const remainingCap = cap - payout;
242	      remainingCaps.set(policyId, remainingCap);
243	      return { payout, remainingCap };
244	    },
245	  };
246	};
247	
248	type QuoteResult = { premium: number };
249	type ClaimResult = { payout: number; remainingCap: number };
250	
251	const isKnownItemType = (type: string): boolean =>
252	  Object.hasOwn(ITEM_BASE_PREMIUMS, type);
253	
254	const processQuote = (
255	  step: QuoteStep,
256	  policyId: number,
257	  customer: Customer,
258	  ledger: PolicyLedger,
259	): QuoteResult => {
260	  for (const item of step.items) {
261	    if (!isKnownItemType(item.type)) {
262	      throw new Error(`unknown item type: ${item.type}`);
263	    }
264	  }
265	
266	  ledger.open(policyId, step.items);
267	  return {
268	    premium: quotePremium(step.items, {
269	      customer,
270	      isFollowUpContract: policyId > 0,
271	    }),
272	  };
273	};
274	
275	const validateDamages = (damages: Damage[], insuredItems: Item[]): void => {
276	  for (const damage of damages) {
277	    if (damage.amount < 0) {
278	      throw new Error(`damage amount must not be negative: ${damage.amount}`);
279	    }
280	  }
281	
282	  const insuredCounts = countByType(insuredItems, itemType);
283	  for (const [type, damagedCount] of countByType(damages, damagedItemType)) {
284	    if (damagedCount > (insuredCounts.get(type) ?? 0)) {
285	      throw new Error(`more damages than insured items of type: ${type}`);
286	    }
287	  }
288	};
289	
290	const processClaim = (step: ClaimStep, ledger: PolicyLedger): ClaimResult => {
291	  const insuredItems = ledger.insuredItems(step.policy);
292	  validateDamages(step.incident.damages, insuredItems);
293	  return ledger.drawDown(
294	    step.policy,
295	    desiredPayout(step.incident.damages, insuredItems),
296	  );
297	};
298	
299	export const runScenario = (scenario: Scenario): ScenarioResults => {
300	  const ledger = createPolicyLedger();
301	
302	  const results = scenario.steps.map((step, index) =>
303	    step.op === "quote"
304	      ? processQuote(step, index, scenario.customer, ledger)
305	      : processClaim(step, ledger),
306	  );
307	
308	  return { results };
309	};
